      "body": "<p>رحلة الحالة في منظومة أوسع مرتبة ولا تقفز خطوة فوق خطوة. تبدأ بالتقييم، ثم يصدر التقرير الذي يحمل بصمة الحالة: تسعة مجالات، ولكل مجال نمطه المختار وحالته، وتوصيات مرتبطة بتلك التركيبة بعينها. لكن التقرير، مهما كانت قراءته عميقة، يبقى وثيقة فهم: يخبرك كيف تستجيب هذه الحالة للعالم الحسي من حولها، وماذا يعني ذلك في يومها، وما الذي ينبغي مراعاته معها. أما الخطة المقدمة فهي الخطوة التي تلي الفهم في الرحلة: برنامج أنشطة شهري يصل الحالة جاهزا، بأنشطة مجدولة يوما بيوم، وبطاقات تعرض لكل نشاط مجاله وخطواته ومواده ومدته. موضع الخطة إذن بعد التقرير لا قبله ولا بديلا عنه، وهي لا تلغي التوصيات ولا تكررها بصيغة أخرى، بل تحمل الحالة من سؤال ماذا نفهم عنها إلى سؤال ماذا نفعل معها كل يوم، وبأي إيقاع، وكيف نتابع ما نفعل. ولهذا كان المستوى الثاني شرطا لهذا المستوى: فمن لا يقرأ البصمة قراءة صحيحة مجالا مجالا لن يقرأ الخطة المبنية عليها قراءة صحيحة، وسيتعامل مع أنشطتها كقائمة مهام منفصلة بدل أن يراها برنامجا واحدا مربوطا بتركيبة حالة بعينها قرأها ووثق بها. من اليوم فصاعدا، كلما فتحت خطة، اسأل أولا: أين تقف هذه الحالة في رحلتها؟ فجوابك يحدد إن كنت تقرأ وثيقة تنفيذ في موضعها الصحيح، أو تقفز إلى التنفيذ قبل اكتمال الفهم.</p>"
