      "head": "2) خطة خالد تصل",
      "body": "<p>تعود هنا إلى خالد الذي رافقك طوال المستوى الثاني، وتستكمل حكايته من حيث توقفت هناك. خالد متعلم في الثالثة من عمره، في فئة 3-14، منعزل يفضل اللعب المنفرد، لا يستجيب لاسمه حين ينادى، غير متكلم، مغرم بقطاره، وفي حركة مستمرة لا تهدأ. قرأت تقريره المحاكي كاملا في المستوى الثاني، وحفظت بصمته مجالا مجالا: في الدهليزية بحث 86 غالب، وفي البصري بحث 74 غالب، وفي الحس العميق بحث 71 غالب، وفي الانتباه والتركيز تسجيل 72 غالب، وفي الأصوات تسجيل 68 غالب، وفي الاجتماعي-العاطفي تجنب 66 غالب، وفي الحس الداخلي تسجيل 63 غالب، وفي اللمسية حساسية 57 متوازن، وفي الشم والتذوق تسجيل 44 متوازن. الآن تصل خطة خالد الشهرية المحاكية، جاهزة كما تصل أي حالة في المنظومة، وتحمل بصمته نفسها مرجعا ظاهرا في أولها. لن نقرأ هذه الخطة كاملة هنا، فقراءتها الكاملة لها درسها المحفوظ لاحقا في هذا المستوى، لكننا نضع أمامك من الآن سؤالا مفتوحا بلا إجابة فورية، ونتركه معلقا عمدا كما فعلنا في مقدمة المستوى الثاني: كيف ستُدار هذه الخطة شهرا كاملا، يوما بيوم وأسبوعا بأسبوع، وكيف سيُقاس أثرها قياسا صادقا لا انطباعيا؟ احتفظ بالسؤال حيا وأنت تعبر الدروس الأولى، فكل درس قادم يضيف حلقة من جوابه: كيف تصل الخطة، وكيف تُقرأ من البصمة، وكيف تُبنى بنية شهرها، قبل أن تفتح خطة خالد نفسها وتقرأها كاملة خطوة بخطوة.</p>"
