      "head": "3) ثيمة دورة الخطة باختصار: خمس حلقات من القراءة إلى إعادة التقييم",
      "body": "<p>الثيمة المنظمة لهذا المستوى كله هي دورة الخطة، وهي خمس حلقات متتابعة، كل حلقة تسلم إلى التي بعدها ولا تصح إذا قُطعت أو قُدمت على سابقتها. الحلقة الأولى هي قراءة الخطة: أن تفتحها بترتيب أقسامها، وتربط كل نشاط فيها بمجاله وبسطر بروفيله، وتفهم بنية شهرها قبل أن تنفذ يوما واحدا منها. والحلقة الثانية هي تنفيذها: أن يتحول كل نشاط من بطاقة مكتوبة إلى فعل حقيقي في غرفة الحالة وبيتها، بتحضير صحيح وخطوات كما تعرضها البطاقة وملاحظة أثناء التنفيذ. والحلقة الثالثة هي الملاحظة والتسجيل: توثيق ما نُفذ ومتى وبأي مستوى، ووصف استجابة المتعلم وصفا دقيقا بزمانه وسياقه، لأن ما لا يُسجل اليوم لا يمكن متابعته غدا. والحلقة الرابعة هي قياس الأثر: قراءة ما تغير فعلا في السلوك اليومي بمؤشرات قابلة للملاحظة، عبر الشهور المتراكمة لا عبر يوم لافت أو أسبوع حماسي. والحلقة الخامسة هي إعادة التقييم في موعدها: قياس جديد يخرج بروفيلا جديدا، فتُقرأ الموازنة بين البروفيلين قراءة مهنية آمنة، وتولد من البروفيل الجديد خطة جديدة تبدأ بها الدورة من أولها مرة أخرى. احفظ صورة الدورة حاضرة من الآن كما حفظت صورة البصمة في المستوى الثاني: كل درس قادم موضعه حلقة من هذه الحلقات، وكل خطأ في إدارة خطة حقيقية هو في الغالب حلقة قُفزت أو حلقة اختلطت بأخرى.</p>"
