      "body": "<p>تنبيهان يحكمان هذا المستوى من أوله إلى آخره، ونعلنهما هنا صراحة حتى لا يلتبس عليك شيء فيما بعد. التنبيه الأول منهجي في طبيعة الخطة نفسها: الخطة وثيقة تنفيذ، لا وثيقة شرح نظري. قيمتها ليست في أن تناقشها أو تعيد صياغة منطقها، بل في أن تُقرأ بترتيبها، وتُنفذ بأنشطتها كما تعرضها بطاقاتها، وتُتابع بسجلها وتقاريرها، وتُقاس بمؤشرات أثرها. فحين تتعامل معها، عاملها كما تعامل بروتوكول عمل معتمدا: تفهمه بدقة، وتطبقه بأمانة، وتلاحظ نتائجه بصدق، ولا تبدل محتواه اجتهادا من عندك ولا من عند الأسرة. والتنبيه الثاني هو حد الأسرار الثاني، وهو امتداد مباشر لحد المستوى الثاني مع آلية التقييم: في هذا المستوى نقرأ الخطة كما تصل إلى المشترك، بمكوناتها الظاهرة وتطابقها الظاهر مع البروفيل، وننفذها ونتابعها ونقيس أثرها، ولا نشرح كيف اختيرت أنشطتها لحالة بعينها، ولا كيف بُنيت الخطة من الداخل، في أي درس ولا في أي نسخة، للعامة ولا للشركاء. هذا الحد ليس نقصا في تأهيلك: فمهمتك كاملة بقراءة الخطة وتنفيذها ومتابعتها وقياسها وشرحها للأسرة بلغة النواتج، ولا تحتاج آلية إنتاجها في أي خطوة منها. وسيعود هذا الحد في مواضعه من الدروس القادمة، وستحتاجه حتما حين يسألك وليّ أو متدرب لماذا اختير هذا النشاط بالذات، فتجيب بحدود دورك بوضوح وهدوء، وتحيل ما تجاوز ذلك إلى الأستاذ عبد الحليم خليلي بالطريقة المعتمدة.</p>"
