      "body": "<p>رحلة المشترك إلى خطته مرتبة بأربع محطات، وكل محطة شرط لما بعدها. المحطة الأولى هي تقرير البروفيل: يُكمل التقييم، فيصدر التقرير الذي يحمل بصمة الحالة مجالا مجالا، بأنماطها وحالاتها وتوصياتها. هذا التقرير هو الأساس الذي تُبنى عليه الخطة في وعي المشترك قبل أي شيء آخر، فلا خطة بلا بروفيل سابق يقرؤه ويحتفظ به مرجعا. والمحطة الثانية هي كود الخطة الفردي: رمز خاص بهذه الحالة وحدها، يفتح لها خطتها هي لا خطة غيرها، ويحفظ خصوصية البرنامج الشخصي فلا يطلع مشترك على أنشطة مشترك آخر ولا تختلط الخطط بين الحالات. والمحطة الثالثة هي صفحة الخطة: الصفحة الواحدة التي تستقبل المشترك بصورة شهره كاملة، من شارة بروفيله إلى أقسام مجالاته، وهي أول ما ينبغي أن يفتحه ويفهمه قبل تنفيذ أي نشاط، وفيها يعيش التنفيذ اليومي الفعلي بأنشطته المصورة ودراسة حالته. احفظ هذا الترتيب كما يعيشه المشترك، لأن شرحك لأي أسرة يبدأ منه: حين تسألك أسرة أين خطتنا، فجوابك ليس رابطا ترسله، بل رحلة تذكرها بها: تقرير قرأتموه، وكود يخصكم، وصفحة خطة ترسم شهركم وتنفذون منها كل يوم. وكل خلل في الوصول لاحقا يُشخص بعودتك إلى هذه المحطات واحدة واحدة: هل صدر التقرير؟ هل الكود صحيح؟ هل فتحت الصفحة المقصودة؟ بهذا التدرج وحده تحل مشاكل الوصول بهدوء وبلا تخبط.</p>"
