      "body": "<p>صفحة الخطة خمسة مكونات ظاهرة بترتيب ثابت، واحفظها بهذا الترتيب لأنك ستسميها للأسرة كما هي. المكوّن الأول هو ترويسة الشهر: اسم الشهر ورقمه من اثني عشر شهرا ومرحلته، وأزرار الأشهر التي يتنقل بها المشترك بين شهوره. والمكوّن الثاني هو شارة البروفيل: اسم الحالة وعمرها وعبارة الصفحة أن هذا بروفيلها الشخصي، وهو الجسر الظاهر بين تقرير الحالة وخطتها، تقرؤه أولا في كل مرة تفتح فيها الصفحة. والمكوّن الثالث هو شريط التقدم الكلي: عدد أنشطة الشهر كما بني على بصمة هذه الحالة، فلا رقم ثابتا يعد به أحد، لأن العدد يتبع حالات مجالات البروفيل: أنشطة للمجال الغالب والكامن، ولا أنشطة للمجال المتوازن، وما أنجز منها حتى اللحظة. والمكوّن الرابع هو أقسام المجالات التسعة: لكل مجال قسمه بوسام نمطه المختار وحالته وعدّاد تقدمه، وداخل القسم بطاقات أنشطته بترتيب التقييم، وللمجال المتوازن جملة الصفحة نفسها أنه لا أنشطة مقترحة له ونص المحافظة عليه بسياقاته الثلاثة: في البيت وفي المدرسة وفي الأماكن العامة. والمكوّن الخامس هو دراسة الحالة في ذيل الصفحة: حالة افتراضية بهدف هذا الشهر تريك كيف يقرأ شهر كامل من بصمته. هذه المكونات الخمسة هي كل ما يحتاجه القارئ ليفهم شهره قبل بدئه، فلا تبحث في الصفحة عما ليس فيها، ولا تتجاوز مكوّنا إلى الذي بعده قبل فهمه.</p>"
