      "head": "3) التنفيذ داخل صفحة الخطة",
      "body": "<p>داخل صفحة الخطة يعيش التنفيذ، والدخول إليها بكود الخطة الخاص بالحالة، وهو موضع أول ما يتحقق منه عند أي مشكلة وصول. يجد المشترك أولا أقسام المجالات بأنشطتها المصورة: أنشطة الشهر المعروضة بصورها وبطاقاتها داخل قسم كل مجال، فيفتح نشاط اليوم منها ويرى خطواته ومواده كما تعرضها نافذة بطاقته. وفي قسم المجال نفسه يجد البطاقة البديلة عند الحاجة: بطاقة أخرى من المجال نفسه مقدمة داخل المنظومة، فمن يبحث عن بديل يبحث في القسم نفسه لا خارج الصفحة. وتضم الصفحة أيضا دراسة حالة الشهر في ذيلها: حالة تعليمية مصاحبة لشهر الحالة، تقرأ للفهم والمقارنة الهادئة لا للنسخ على الحالة نفسها. وتحمل كل بطاقة في نافذتها هدفها الوظيفي واستراتيجية مرحلتها وخطواتها مرقمة بصورها، فلا يتوقف التنفيذ عند غموض ولا تُفسر الخطوات اجتهادا. اعرف هذه المحتويات بمواضعها: الدخول بالكود، وأقسام المجالات ببطاقاتها المصورة، والبطاقة البديلة من القسم نفسه، ودراسة الحالة، فأغلب أسئلة الأسر العملية جوابها واحد منها.</p>"
