      "head": "4) الفرق الوظيفي بين صفحتي الخطة والأنشطة",
      "body": "<p>الخلط بين موضعي الصفحة الواحدة هو أكثر أخطاء الاستعمال شيوعا، وعلاجه جملة وظيفية واحدة تحفظها وتقولها لكل أسرة: أعلى الصفحة وأقسامها خريطة الشهر وإيقاعه، وبطاقات الأنشطة داخل الأقسام مكتبة التنفيذ وتفاصيلها. إلى الخريطة ترجع حين تسأل أسئلة الشهر الكبيرة: ما بروفيلنا باختصار؟ كم نشاطا في شهرنا وأين نقف في شريط التقدم؟ ما وسام كل مجال وحالته؟ أما إلى البطاقات فترجع حين تسأل أسئلة اليوم العملية: ما نشاط اليوم وكيف ينفذ خطوة بخطوة؟ ما البديل إن تعذر الأصلي؟ ما معنى هذا المصطلح؟ ماذا في دراسة حالة هذا الشهر؟ الخريطة لا تنفذ منها الأنشطة، والمكتبة لا تقرأ منها صورة الشهر الكاملة، ومن يستعمل كل موضع في وظيفته لا يضيع وقته ولا وقت أسرته في البحث في الموضع الخاطئ. ويتصل بهذا الفرق عنصر ثالث لا يصلك من خارج الصفحة بل تقرؤه منها دوريا: تقدم الخطة كما يعرضه شريط التقدم الكلي وعدّادات أقسام المجالات وعلامات الإنجاز على البطاقات، تراجعه أسبوعيا من سجل التنفيذ فتعرف ما أنجز وما تقدم تنفيذه وما يحتاجه الأسبوع القادم، وستتعلم قراءته قراءة صحيحة في درس المتابعة لاحقا. فرّق إذن بين ثلاثة: خريطة تفتحها، ومكتبة تنفذ منها، وتقدم تراجعه.</p>"
