      "head": "5) فئتا الخطة (0-3 و3-14)",
      "body": "<p>ترد الخطة في منظومة أوسع لفئتين عمريتين فقط: فئة 0-3 وفئة 3-14، ولا توجد في هذا البناء فئة غيرهما، فلا تسمّ فئة من عندك ولا تقس خطة على تقسيم آخر تعرفه من خارج المنظومة. الفئة ليست تفصيلا إداريا في أعلى الصفحة، بل هي إطار يضبط ما يصل الحالة: فمواد الأنشطة وأحجامها ومستويات خطواتها وطبيعة مشاركة الراشد تختلف باختلاف عمر المتعلم وقدراته في كل فئة، لذلك تُقرأ كل خطة داخل فئتها ولا تُنقل أنشطتها ولا توقعاتها من فئة إلى أختها. خالد الذي يرافقنا في هذا المستوى عمره 3 سنوات، وهو في فئة 3-14، فكل ما ستقرؤه في خطته لاحقا يُقرأ بمعايير فئته هو: نشاط واحد يوميا بمدة بطاقته، وخطوات تناسب بداية هذه الفئة، ودور للراشد المرافق كما تعرضه بطاقات أنشطته. أما البنية الظاهرة العامة التي درستها في هذا الدرس، من محطات الوصول ومكونات صفحة الخطة الخمسة ومحتويات أقسامها، فهي إطار العرض المشترك الذي ترد به الخطط للمشتركين، مع ضبط فروق كل فئة على صفحات الأداة كما تظهر للمشترك في فئته. قاعدتك العملية إذن مزدوجة: اسأل أولا عن فئة الحالة قبل أن تتكلم عن خطتها، ثم اقرأ خطتها بمكوناتها الظاهرة داخل تلك الفئة وحدها، ولا تستعير حكما ولا نشاطا ولا توقعا من الفئة الأخرى.</p>"
