      "head": "5) أخطاء قراءة الربط",
      "body": "<p>تختم بأخطاء تتكرر في قراءة ربط الخطة بالبصمة، وأولها وأشهرها خطأ الأسبوع الواحد: أن يراجع قارئ أسبوعا واحدا من التنفيذ فلا يجد فيه نشاطا منفذا لمجال بعينه، فيستنتج أن الخطة أهملت ذلك المجال أو نسيته. هذا الاستنتاج باطل منهجيا، لأن تغطية المجالات تُقرأ على الشهر كاملا لا على أسبوع واحد: فأنشطة الشهر تتوزع على مجالاته الفعالة (الغالبة والكامنة)، وتوزيعها على الأسابيع قد يكثف مجالا في أسبوع ويهدئه في آخر، والمجال المتوازن لا نشاط له أصلا بحكم حالته لا بحكم التوزيع، ولا يحكم على هذا التوزيع إلا من قرأ أقسام الخطة كلها من أولها إلى آخرها قبل بدء التنفيذ، وهو موضوع درس بنية الشهر التالي بتفصيله. الخطأ الثاني هو ربط النشاط بمجال من انطباعك لا من بطاقته: نشاط يبدو لك حركيا فتنسبه إلى الدهليزية، بينما سطر مجاله المعتمد في بطاقته يقول غير ذلك، وعلاج هذا الخطأ هو خطوتا الدرس الأولى: اقرأ السطر كما هو، دائما. والخطأ الثالث هو القفز من التطابق الظاهر إلى تفسير داخلي: أن تقول للأسرة اختير هذا النشاط لأن المنظومة رأت كذا وكذا، فتخترع سببا لا يظهر في أي صفحة، وعلاجه حد الأسرار الثاني الذي لا يتجاوز. والخطأ الرابع هو قراءة خطة بلا بصمتها: فتح الأقسام والبطاقات مع إهمال شارة البروفيل أعلى الصفحة، فتتحول القراءة إلى تنفيذ أعمى. احفظ القاعدة الجامعة: كل نشاط يُقرأ من بطاقته، وكل بطاقة تُقرأ على ضوء سطر مجالها في البروفيل، وكل خطة تُحكم تغطيتها على شهرها كاملا.</p>"
