      "body": "<p>بعد البطاقات، ارجع إلى أقسام المجالات واقرأ وساماتها وعدّاداتها قراءة ثانية بوصفها خريطة تقدم خطته كما وصلته، لا بوصفها زخرفة في الصفحة. كل قسم يعرض وسام نمطه المختار وحالته: سبعة أقسام بوسام غالب تحمل ثلاثة أنشطة لكل منها، وقسمان بوسام متوازن يظهران بين قوسين لا أنشطة فيهما، وعدّاد تقدم كل قسم يبدأ من صفر ويتحرك بتعليم الإنجاز على بطاقاته، وفوق الأقسام شريط التقدم الكلي: صفر من 21 نشاطا في أول الشهر. ارجع كل وسام إلى سطر بروفيله الذي يتصل به، كما أرجعت كل نشاط إلى مجاله؛ فالوسام الذي لا تستطيع ربطه بسطر في بروفيله أعد قراءته قبل أن تستعمله. ولاحظ ما تلفت إليه هذه القراءة منفذ الخطة فعلا: قسم الدهليزية بوسام بحث غالب يتصدر خطته بأنشطة الحركة المنظمة، فموضعه في يوم المتعلم ليس هامشيا، وأقسام التسجيل الغالب تحتاج انتباها خاصا حتى لا تمر أنشطتها مرورا عابرا، والقسمان المتوازنان يقرآن بجملة الصفحة نفسها: لا أنشطة مقترحة، مع نص المحافظة بسياقاته الثلاثة. ولاحظ حدود هذا في كلامك مع الأسرة: تشرح الوسام والعدّاد كما وردا وأثرهما العملي في التنفيذ، ولا تحولهما إلى وعد بنتيجة، ولا تقدمهما قاعدة عامة تصلح لكل حالة؛ فهي خريطة مبنية على بروفيل خالد، تقرأ في خطته وتستعمل في شهره، كما هي بطاقاته وأنشطته.</p>"
