      "body": "<p>في مقدمة هذا المستوى كتبت سطرين عما تتوقع أن تجده في خطة خالد انطلاقا من بصمته، واحتفظت بهما لهذه اللحظة. أخرجهما الآن ووازن. غالبا توقعت ما يتوقعه كل قارئ للبصمة: شهرا تطغى عليه أنشطة الحركة والدهليزية والحس العميق، وربما غيابا أو حضورا رمزيا للمجالات الهادئة. فماذا وجدت فعلا؟ وجدت توزيعا يتبع البصمة سطرا سطرا: 3 أنشطة لكل مجال غالب من المجالات السبعة، بما فيها الأصوات والانتباه والتركيز والحس الداخلي، ومجالان متوازنان، اللمسية والشم والتذوق، لا أنشطة لهما بحكم حالتهما، مع نص محافظة يقرأ بسياقاته الثلاثة. ووجدت أن مخاطبة القطب الكبير لا تعني إهمال القطب المقابل، بل العكس: أنشطة التسجيل حاضرة بخطوات تقرب المنبه خطوة خطوة. وربما فاجأك موضع نشاط بعينه، كأن يبدأ قسم الانتقال والتنظيم الذاتي من جدول بصري يرتبه المتعلم بيده لا من نشاط جماعي مباشر؛ فارجع إلى بطاقته وستجد التعليل معروضا فيها نفسها: تسلسل مرئي متوقع، وإشارة إلى البطاقة الحالية قبل الانتقال، وإنهاء بتحريك البطاقة المنجزة. الموازنة الصادقة هنا هي درس المستوى كله في حالة واحدة: التوقع يبنى من البصمة وحدها، والخطة تقرأ كما وصلت كاملة، والفرق بينهما هو ما تتعلم منه قراءة أي خطة قادمة بلا استباق ولا قفز.</p>"
