      "body": "<p>خطة هذا الدرس خطة تدريبية محاكية كاملة، بنيت خصيصا لهذا الدرس ببنية الخطة الحقيقية الظاهرة للمشترك، وهي حالة افتراضية تعليمية امتدادا لقرار بناء التقرير المحاكي في المستوى الثاني وموسومة بذلك في موضعها. أقسامها هي أقسام الخطة الفعلية: ترويسة شهر وشارة بروفيل وشريط تقدم، وأقسام مجالات تسعة، وبطاقات أنشطة، ودراسة حالة، بأنشطتها الثلاثة المتتبعة هنا ببطاقاتها الكاملة كما ستستعملها في دروس التنفيذ والمتابعة القادمة من هذا المستوى. وحدود استعمالها واضحة وصارمة: هي أداة تدريب على قراءة الخطة وإدارتها، فلا تنقل أنشطتها ولا توزيعها ولا اقتراحاتها إلى أي حالة حقيقية، ولا تقس عليها خطة أخرى؛ فلكل حالة خطتها التي تصلها ببروفيلها، كما أن لكل حالة بصمتها التي لا تتكرر. وحين تصلك بعد اليوم خطة حقيقية في عيادتك، استعمل الترتيب نفسه والأسئلة نفسها وربط البطاقة بمجالها نفسه، ودع أنشطة تلك الخطة تتكلم عن حالتها وحدها. بهذا تكون قد أكملت الحلقة الأولى من دورة الخطة: قراءتها كاملة، وتستعد للحلقة التالية: تنفيذها نشاطا نشاطا.</p>"
