      "body": "<p>يبدأ التنفيذ الصحيح قبل النشاط لا عنده. أولا: اجمع المواد من البيت كما تسميها البطاقة حرفيا، ولا تستبدل مادة جوهرية بما يشبهها من عندك؛ فإن تعذرت مادة أساسية فهذا موضع بطاقة بديلة من قسم المجال نفسه كما درست، لا موضع الارتجال. في مسار الزحف المنظم يعني التحضير: ترتيب الوسائد والطاولة والبطانية نفقا في غرفة واسعة، وفحص ثبات المسار وسلامته قبل أن يدخل المتعلم. ثانيا: هيئ المكان: مساحة خالية من العوائق، وإزاحة ما يشتت أو يخيف، وإغلاق مصادر الضجيج المفاجئ ما أمكن. ثالثا: اختر الوقت الذهبي كما يعلّم هذا المستوى، وهو حين يكون المتعلم هادئا ويقظا: لا جائعا ولا نعسا ولا خارجا لتوه من موقف مجهد، وثبت هذا التوقيت تقريبا كل يوم حتى يصير النشاط جزءا متوقعا من اليوم. رابعا: أطفئ الشاشات قبل النشاط بنصف ساعة لتهيئة الحواس، وعلّم الأسرة أن هذه النصف ساعة جزء من النشاط لا مقدمة اختيارية له. وخامسا: راجع خطوات البطاقة مرة أخيرة بصوت خافت لنفسك، وحدد دور كل راشد حاضر؛ فدقائق النشاط قصيرة، ولا تحتمل قراءة أولى أثناء التنفيذ.</p>"
