      "head": "3) أثناء التنفيذ",
      "body": "<p>النشاط في هذه المنظومة نشاط عائلي يشارك فيه الراشد، لا مهمة تسلم للمتعلم ويراقب من بعيد. أنت داخل النشاط: تزحف أولا نموذجا في مسار الزحف المنظم، وتعرض السماعات بنفسك في اختيار سماعات الحماية، وترتب البطاقات مع المتعلم في الجدول البصري للانتقال. ولا يترك المتعلم وحده أبدا أثناء التنفيذ، في أي نشاط، ولو بدا مندمجا ومستقلا؛ فحضورك جزء من أمان النشاط ومن قراءته معا. ونفذ الخطوات بترتيب البطاقة كما هي، وبإيقاع هادئ لا يستعجل الانتقال من خطوة إلى خطوة: في مسار الزحف المنظم حركات بطيئة خطية أولا، والتوقف عند أول علامة دوار جزء من الخطوة لا فراغ بين الخطوات؛ وفي الجدول البصري للانتقال إشارة إلى البطاقة الحالية قبل أي انتقال، وترك المتعلم يحرك البطاقة المنجزة بنفسه جزء من الخطوة لا تأخير عنها. واجعل صوتك وتعليماتك قصيرة وواضحة، نشاطا واحدا وطلبا واحدا في كل لحظة، حتى يبقى انتباه المتعلم داخل النشاط لا مشتتا بين كلامك وموادك وحركتك. فإذا انقضت دقائق النشاط كما في بطاقته وأنت في منتصف خطوة أخيرة، أكملها بهدوء ثم انتقل إلى الإنهاء كما في القسم قبل الأخير.</p>"
