      "head": "4) الأسبوع الكامل",
      "body": "<p>انظر إلى الشهر أسبوعا أسبوعا، لا يوما بيوم فقط. فأنشطة الشهر تتوزع على أقسام مجالاته الفعالة، وهي بترتيب التقييم المعتمد: 1 الأصوات، 2 البصري، 3 اللمسية، 4 الشم والتذوق، 5 الحس العميق، 6 الدهليزية، 7 الحس الداخلي، 8 الاجتماعي-عاطفي، 9 الانتباه والتركيز. ومعنى ذلك أن أنشطة الأسبوع تتوزع على مجالات الشهر الفعالة بلا احتكار: فمجال فعال قد يغيب أسبوعا ويحضر في غيره، والمجال المتوازن غائب عن الأنشطة كلها بحكم حالته لا بحكم التوزيع. لذلك اجعل الأسبوع وحدة متابعة لا وحدة حكم. في نهاية كل أسبوع تنظر نظرة هادئة: كم نشاطا نفذ من سبعة، وأين وقع الفوات ولماذا، وهل ظهر رفض متكرر يستحق أن يقرأ في درس الرفض التالي، وهل ثبت موعد التنفيذ أم ما زال يتنقل. أما الحكم على نجاح الخطة أو فشلها من أسبوع واحد، وخاصة من الأسبوع الأول الذي ما زالت فيه الأسرة والمتعلم في طور التعرف على الأنشطة وعلى الإيقاع نفسه، فهو حكم متسرع ستدرب نفسك على رفضه. التدرج عبر الشهور بمراحلها يعني أن شهور الخطة ليست متماثلة أصلا: أولها للتثبيت والاكتشاف، وتاليها للتوسع والتنويع، ومتقدمها للتعمق والتعميم ثم القيادة والاستقلالية، فلا تقارن شهر اكتشاف بمعيار شهر متقدم. الأسبوع عندك مرآة إيقاع، لا منصة إصدار أحكام.</p>"
