      "head": "5) واقعية الأسر",
      "body": "<p>الأسر التي تنفذ الخطة تعيش حياة كاملة خارجها: عمل ودراسة ومرض وزيارات ومناسبات وأيام يضطرب فيها كل شيء. أسبوع مضطرب لا يهدم خطة، وهذه جملة يجب أن تسمعها الأسرة منك بوضوح قبل أن تحتاجها، لأن كثيرا من الانقطاعات النهائية لا تحدث بسبب الأسبوع المضطرب نفسه، بل بسبب شعور الأسرة بعده أن الخطة انكسرت وأن العودة لم تعد نظيفة. مهمتك أن تعيد تعريف الاستمرار لها: الاستمرار هو أن نعود إلى الجدول من موضعه بعد الاضطراب، لا أن نمنع الاضطراب من الحدوث. فإذا طال الانقطاع لأيام متتالية بسبب سفر أو مرض أو ظرف عائلي كبير، فالاستئناف يكون من الشهر الجاري نفسه بمراجعة سريعة: أين توقفنا في الجدول، وماذا سجلنا عن أيام الفوات، وما نشاط اليوم الذي عدنا فيه، ثم نمضي قدما. لا استئناف من الصفر، ولا إعادة للشهر من أوله، ولا أنشطة تعويض متراكمة تنتظر الأسرة عند عودتها. وحين تراجع أسرة متوترة، ابدأ بما نفذ فعلا قبل أن تتكلم عما فات، فالصورة الكاملة لشهر فيه أيام فوات موثقة وأيام تنفيذ ثابتة هي صورة خطة حية تعمل، لا صورة فشل. الواقعية هنا ليست تساهلا، بل هي شرط بقاء الخطة حية حتى نهاية دورتها.</p>"
