      "head": "6) موضع جلسات العيادة عند الشريك",
      "body": "<p>الخطة منزلية التنفيذ أساسا، وهذه نقطة يجب أن تبقى واضحة عندك وعند الأسرة معا. الأسرة تنفذ النشاط اليومي في البيت، في الوقت الذهبي الذي ثبتته، وتسجل تنفيذه واستجابة المتعلم له. أما جلسة العيادة عندك أنت الشريك، فموضعها مختلف تماما: هي للشرح قبل بدء الشهر، وللمتابعة أثناءه، وللقياس ومراجعة السجل عند مواعيدها، لا لتنفيذ أنشطة الشهر كلها داخل العيادة نيابة عن البيت. فإذا حولت جلساتك إلى مسرح تنفيذ لكل نشاط، أفرغت الخطة من طبيعتها المنزلية، وحرمت الأسرة من دورها المنفذ الذي هو قلب النموذج، وحرمت نفسك من بيانات التنفيذ الحقيقي في البيئة الطبيعية للمتعلم. وفي عيادة تدير حالات متعددة في الشهر نفسه، يصبح ضبط الإيقاع مهارة إدارية عندك: لكل حالة موعد متابعة معروف، وسجل يراجع في موعده، وأسئلة تجمع وتجاب في الجلسة لا عبر مرافقة يومية مبعثرة. وبهذا التوزيع الواضح للأدوار يبقى البيت موضع التنفيذ، وتبقى العيادة موضع القراءة والضبط والقياس، وتبقى الخطة قابلة للإدارة لأكثر من حالة دون أن تتحول إلى عبء يومي عليك أو على الأسر.</p>"
