   "intro": "<p>في نهاية هذا الدرس تستطيع أن تتعامل مع رفض النشاط أو فشله تعاملا مهنيا هادئا، بمرونة تقدمها المنظومة نفسها داخل الخطة، وتربي به أسر حالاتك على قراءة الرفض بوصفه معلومة تستحق الفهم لا سلوكا يستحق المواجهة. فكل منفذ سيواجه يوما ينسحب فيه المتعلم من النشاط، أو يدفعه بعيدا، أو يبكي عند بدئه، أو يتجاهله تماما، ولحظة الرفض هذه هي التي تنكشف فيها مهنيتك: هل تتحول ربع الساعة الهادئة إلى صراع إرادات يخسر فيه الجميع، أم تبقى لحظة قراءة منضبطة بسلم واضح تعرفه الأسرة مسبقا وتطبقه دون ارتجال. هذا الدرس لا يقدم حيلا لإجبار المتعلم على القبول، بل يقدم العكس تماما: مبدأ معلنا في الخطة نفسها، وسلما مرتبا للاستجابة، وقراءة مهنية للرفض المتكرر، وممنوعات صريحة لا تتجاوز، وحدا واضحا يتحول عنده الرفض من ملاحظة يومية إلى إشارة ترفع بالطريقة المعتمدة.</p>",
