      "head": "2) سلم الاستجابة للرفض بترتيبه",
      "body": "<p>للاستجابة للرفض سلم مرتب لا يقفز فيه المنفذ من خطوة إلى أخرى، وترتيبه جزء من معناه. الخطوة الأولى هي الإيقاف الهادئ دون إلحاح: عند إشارة رفض واضحة يوقف النشاط بهدوء، وتجمع أدواته دون تعليق غاضب ودون محاولة أخيرة للإقناع، ويترك المتعلم يستعيد هدوءه. الخطوة الثانية هي فحص السياق قبل أي حكم على النشاط نفسه: هل الوقت غير مناسب، هل المتعلم متعب أو جائع، هل البيئة صاخبة أو مزدحمة، هل سبق النشاط انتقال مفاجئ أو انقطاع عن نشاط محبب. كثير من حالات الرفض تفسر كاملة في هذه الخطوة وحدها. الخطوة الثالثة هي تجربة تبسيط خطوة النشاط نفسه في محاولة لاحقة، لا في اللحظة نفسها، فالتبسيط يخفض مطلب النشاط مع بقائه نشاط المجال نفسه وهدفه نفسه. الخطوة الرابعة هي التأجيل إلى الغد حين لا تناسب المحاولة اللاحقة يوم الرفض، فيسجل النشاط مؤجلا ويمضي اليوم إلى روتينه الطبيعي. الخطوة الخامسة هي تسجيل ما حدث بوصفه ملاحظة موصوفة: ماذا عرض، ومتى ظهر الرفض، وماذا كان في السياق، وماذا فعل المنفذ. طبّق السلم كاملا بهذا الترتيب، فتخطي الفحص إلى التبسيط مباشرة قد يبسط نشاطا لم تكن مشكلته صعوبته أصلا، وتخطي التسجيل يحرمك من المادة التي ستحتاجها لقراءة الرفض المتكرر.</p>"
