      "head": "4) ما لا يفعل أبدا",
      "body": "<p>مقابل المرونة المشروعة توجد ممنوعات صريحة احفظها وعلّمها للأسرة بوصفها خطوطا لا تتجاوز مهما اشتد إغراء إكمال نشاط اليوم. لا إجبار جسديا أبدا، كإمساك يد المتعلم لتنفيذ خطوة رفضها، ولا إجبار معنويا بالضغط المتكرر أو التوبيخ أو المقارنة بغيره. ولا يحول النشاط أبدا إلى عقاب، فلا يقال للمتعلم إن نشاط اليوم صار واجبا مضاعفا لأنه أساء التصرف، لأن النشاط عندها يفقد معناه الحسي المنظم ويتحول في ذهن المتعلم إلى أداة تأديب يقاومها أكثر. ولا تجعل الحركة واللعب مكافأة مشروطة بالهدوء، فلا تحجب الحركة حتى يجلس المتعلم هادئا أولا، وترد على هذا الخلط توصيات خالد العامة نفسها: الحركة الآمنة المنظمة جزء ثابت من يومه لا مكافأة بعد الهدوء، فحاجة بصمته الحركية المرتفعة لا تعلق على شرط سلوكي، بل تلبي بانتظام لأنها جزء من تنظيم يومه. ولا تكرر المحاولة في اليوم نفسه مرة بعد مرة حتى ينكسر المتعلم أو ينكسر المنفذ، فالمحاولة اللاحقة في السلم تعني وقتا لاحقا مناسبا بعد فحص السياق، لا حصارا متصاعدا داخل اليوم الواحد. هذه الممنوعات ليست لطفا زائدا، بل هي ما يحفظ ثقة المتعلم بالنشاط وبمن ينفذه معه عبر الشهر كله.</p>"
