      "head": "5) متى يتحول الرفض إلى إشارة رفع",
      "body": "<p>يبقى الرفض اليومي والرفض المتكرر لمجال بعينه مادة للقراءة والضبط داخل خطتك مع الأسرة، لكن للرفض حدا يخرج عنده من نطاق المرونة اليومية إلى نطاق الإشارة التي ترفع. يتحقق هذا الحد حين يكون الرفض شاملا، يمتد إلى أنشطة الشهر بمجالاتها المختلفة لا إلى مجال واحد أو وقت واحد، ومستمرا لأيام متتالية، ورغم تطبيق المرونة الكاملة: الإيقاف الهادئ، وفحص السياق وتعديله، وتبسيط الخطوة، والتأجيل. عندها لا يكون الجواب المهني مزيدا من الإصرار ولا تجريب حيل جديدة من عندك، بل التوثيق الدقيق لما حدث يوما بيوم، ثم رفع الأمر بالطريقة المعتمدة التي ستفصل في درس الإحالة الأخير من هذا المستوى. وميز للأسرة مبكرا بين مستويين حتى لا تقلق بلا داع ولا تتأخر عند اللزوم: رفض نشاط أو أنشطة مجال في ظروف مفهومة أمر تعالجه الخطة بمرونتها، أما الرفض الشامل المستمر رغم كل المرونة فهو إشارة مختلفة تسجل وترفع ولا تحملها الأسرة وحدها. وحين توثق للرفع، وثّق بالوصف لا بالأحكام: الأيام، والأنشطة المعروضة، والسياقات، والخطوات التي جربت من السلم، فهذا التوثيق هو ما يجعل الإحالة مفيدة لمن يستلمها وقابلة للقرار.</p>"
