   "intro": "<p>في نهاية هذا الدرس تستطيع أن تبني عندك وعند أسر حالاتك عادة تسجيل قصيرة ومنتظمة ترافق تنفيذ الخطة يوما بيوم، وتستطيع أن تفرق بدقة بين تسجيل التنفيذ وتسجيل الأثر، وأن تصوغ ملاحظة يومية موصوفة تصلح مادة لمراجعة الأسبوع وقياس الأثر وقراءة إعادة التقييم في موعدها. فالخطة بلا سجل تنفذ ثم تتبخر: تبقى في الذاكرة انطباعات عامة عن شهر مضى، ولا يبقى دليل واحد موصوف يمكن أن تبنى عليه قراءة مهنية. أما الخطة المسجلة جيدا فتتحول أيامها إلى بيانات حية: ماذا نفذ، وماذا فات ولماذا، وكيف استجاب المتعلم، وماذا تغير عبر الأسابيع. هذا الدرس هو وقود كل ما بعده في دورة الخطة، لأن المتابعة الأسبوعية والشهرية وقياس الأثر وإعادة التقييم لا تقرأ النوايا ولا الانطباعات، بل تقرأ ما سجل في وقته بصياغة سليمة. وسترى في ختامه سجل خالد التنفيذي المحاكي مثالا كاملا على شهر مسجل جيدا، وماذا يكشفه التسجيل المنظم عن حالة بعينها عبر أسابيعها.</p>",
