      "head": "3) البساطة شرط الاستمرار",
      "body": "<p>سجل لا يستمر لا قيمة له مهما بلغت دقته النظرية، وشرط استمرار السجل اليومي هو بساطته القصوى. ثلاث خانات تكفي يوميا، وهي خانات سجل هذا المستوى المعتمدة: تم أو لم يتم، والاستجابة بكلمات قليلة، وملاحظة واحدة. الخانة الأولى تضبط التنفيذ، والثانية تلتقط الاستجابة في أقصر صورة ممكنة مثل اندماج كامل، أو قبول متردد، أو رفض فوري، والثالثة تحمل المشهد الموصوف الواحد الذي يستحق أن يبقى من اليوم كله. سطر واحد لكل يوم خير من فقرة مطولة تكتب مرة واحدة بحماس ثم تهجر بقية الشهر، لأن قيمة السجل في تراكمه المنتظم عبر الأسابيع، لا في بلاغة يوم واحد منه. وحين تشتكي أسرة من ضيق وقتها، لا تخفف عنها بتقليل أيام التسجيل، بل خفف عنها بتقصير التسجيل نفسه: الخانات الثلاث لا تحتاج أكثر من دقيقة واحدة بعد النشاط، إذا كتبت في وقتها. ثبّت موضع السجل وموعد كتابته كما ثبت موعد النشاط نفسه: السجل بجوار أدوات التنفيذ أو في موضع معروف واحد، والكتابة فور انتهاء النشاط أو في نهاية اليوم على أبعد تقدير. وابن عند الأسرة قناعة مركزية في هذا الدرس: اليوم الذي يسجل بسطر واحد صادق أثمن مهنيا من أسبوع كامل يستعاد من الذاكرة في جلسة المتابعة.</p>"
