      "head": "5) سجل خالد التنفيذي",
      "body": "<p>اختم بقراءة سجل خالد التنفيذي المحاكي، وهو شهر كامل مسجل بالخانات الثلاث نفسها التي دربت عليها في هذا الدرس: تم أو لم يتم، والاستجابة بكلمات قليلة، وملاحظة واحدة لكل يوم. خالد متعلم في الثالثة من عمره، ضمن فئة 3-14، غير متكلم، يحب قطاره، وبصمته التي قرأتها في المستوى الثاني تتصدرها الدهليزية بحثا 86 بحالة غالب، ثم البصري بحثا 74، والحس العميق بحثا 71، والانتباه والتركيز تسجيلا منخفضا 72، والأصوات تسجيلا منخفضا 68، والاجتماعي-عاطفي تجنبا 66، والحس الداخلي تسجيلا منخفضا 63، واللمسية حساسية 57 بحالة متوازن، والشم والتذوق تسجيلا منخفضا 44 بحالة متوازن. في سجله يوم سلس نموذجي: نفذ نشاط دهليزي في موعده، وكتبت الاستجابة اندماجا كاملا، وحملت الملاحظة مشهد بقائه منجذبا حتى نهاية النشاط. وفيه يوم رفض موصوف: رفض نشاط أصوات عند ارتفاع ضجيج البيت، وسجل سبب الرفض في خانة الملاحظة بدل أن يسجل حكما على اليوم. وفيه أيام فوات بسبب سفر ونوم مضطرب سجلت ظروفا لا إخفاقا، كما يقتضي حكم اليوم الفائت. وعبر الأسابيع يكشف السجل المتراكم ما لا يكشفه أي يوم منفرد: أنشطة الدهليزية هي الأعلى تنفيذا واندماجا في شهره كله، بينما تحتاج أنشطة الانتباه والتركيز إلى تقصير وتوقيت أبكر لتظهر استجابة أفضل. هذه الخلاصة لم تأت من انطباع، بل من تراكم أسطر قصيرة صادقة، وهي النموذج الذي تطلبه من كل سجل يعرض عليك.</p>"
