      "head": "1) قراءة التقدم الأسبوعية من صفحة الخطة نفسها",
      "body": "<p>تقدم الخطة لا يصلك من خارجها، بل تقرؤه من صفحة الخطة نفسها في مراجعة أسبوعية خفيفة تجريها أنت من سجل التنفيذ، وهو قراءة مهنية لا وثيقة تعدها الأسرة ولا تقرير تطلبه من أحد. تحمل الصفحة ثلاثة عناصر ظاهرة تقرأ بترتيبها وحدودها. العنصر الأول هو شريط التقدم الكلي: ما نفذ فعلا من أنشطة الشهر كما علم على بطاقاته، وهو سجل تنفيذ يجيب عن سؤال ماذا تم، لا عن سؤال ماذا تحسن. والعنصر الثاني هو عدّادات أقسام المجالات: المجالات التي تقدم تنفيذ أنشطتها وتغطيتها خلال الأسبوع، بمعنى أن أنشطتها نفذت وغطيت أكثر من غيرها في هذا الأسبوع. وكلمة تقدم هنا وصف تنفيذ وتغطية، لا حكم بأن المجال تحسن سريريا ولا بأن أثره اكتمل. والعنصر الثالث هو ما يبنيه الشريك من هاتين القراءتين: انتباه الأسبوع القادم، أي ما يوجه إليه التنفيذ التالي في ضوء ما نفذ، يقرأ بوصفه تنظيم متابعة، لا بوصفه تعديلا في محتوى الخطة ولا وعدا بنتيجة. فإذا قرأت التقدم بهذه الحدود الثلاثة كنت قارئا مهنيا له: تلخصه للأسرة في ثلاثة أسطر، سطر لما أنجز، وسطر للمجالات التي تقدم تنفيذها، وسطر لانتباه الأسبوع القادم، دون أن تضيف إليه حكم تحسن لم يقله، ودون أن تحوله إلى بشرى أو إلى إنذار. أما الحكم على الأثر فله درسه الخاص ومؤشراته الخاصة، وموضعه بعد تراكم الشهور لا في أسبوع واحد.</p>"
