      "head": "2) مراجعة الأسبوع من السجل",
      "body": "<p>قراءة التقدم من الصفحة وحدها لا تكفي لمراجعة مهنية، لأن السجل اليومي يحمل ما لا يحمله الملخص: أسباب الفوات، وأنشطة الرفض، وظروف التنفيذ. فمراجعة الأسبوع تبدأ من السجل، وتبنى على أربعة عناصر مرتبة. أولها نسبة الإنجاز الفعلية: عدد الأنشطة المنفذة من أنشطة الأسبوع كما هي مسجلة بتعليم الإنجاز على بطاقاتها، تقرأ رقما وصفيا بسيطا، لا درجة نجاح ولا علامة تقصير. وثانيها أيام الفوات وأسبابها المسجلة: يوم فات لمرض أو سفر أو اضطراب نوم يقرأ ظرفا موثقا، ويوم فات بلا سبب مسجل يقرأ سؤال متابعة عن الإيقاع والموعد، لا اتهاما للأسرة. وثالثها أنشطة الرفض المتكرر: نشاط رفض مرة واحدة في يوم مضطرب غير نشاط يرفض في كل مرة يعرض فيها، والتكرار هو ما يستحق الانتباه وربطه بسياقه وبمجاله عند المراجعة. ورابعها تعديلات الأسبوع القادم المشروعة داخل مرونة الخطة المقدمة: ضبط توقيت النشاط في الوقت الذهبي نفسه تقريبا، وإعادة ترتيب أيام داخل الأسبوع عند الحاجة، واللجوء إلى تبسيط خطوة نشاط بعينه عند الحاجة. هذه التعديلات تنظيم تنفيذ لا مساس بمحتوى الخطة نفسها: لا نشاط يستبدل من خارجها، ولا نشاط يضاف إليها، ولا نشاط يحذف من شهرها. بهذا الحد الواضح تبقى المراجعة داخل دورك: تقرأ وتنظم وتتابع، وتحفظ للخطة وحدتها كما وصلت.</p>"
