      "head": "3) مراجعة اكتمال الشهر",
      "body": "<p>عند اكتمال الشهر تجرى مراجعة أوسع من مراجعات الأسابيع، لأن الشهر هو وحدة الخطة الكاملة: أنشطته تغطي مجالات البروفيل الفعالة كلها، بترتيب التقييم المعتمد: 1 الأصوات، 2 البصري، 3 اللمسية، 4 الشم والتذوق، 5 الحس العميق، 6 الدهليزية، 7 الحس الداخلي، 8 الاجتماعي-عاطفي، 9 الانتباه والتركيز. وتبنى مراجعة اكتمال الشهر على أربعة عناصر لا تسقط منها واحدا. العنصر الأول صورة الإنجاز والفوات معا: ما نفذ من الشهر، وما فات منه، ولماذا فات كما هو مسجل، لأن مراجعة تذكر المنفذ وتنسى الفائت وأسبابه مراجعة ناقصة تضلل الشهر التالي. والعنصر الثاني المجالات الأكثر تنفيذا والأقل تنفيذا: أين تركز التنفيذ فعلا، وأين تعثر، وهل تعثر مجال بعينه تكرارا يستحق أن يحمل تنبيها إلى الشهر التالي. والعنصر الثالث ملاحظات الأثر المتراكمة: ما سجلته الأسرة من استجابات موصوفة عبر الأسابيع، تقرأ مادة أولية لقياس الأثر في الدرس التالي، لا أحكاما جاهزة هنا. والعنصر الرابع ما سيحمل إلى الشهر التالي سؤالا أو تنبيها: توقيت يحتاج ضبطا، أو مجال يحتاج انتباها في التغطية، أو نمط رفض يحتاج مراقبة هادئة. وتكتب هذه المراجعة وتوثق، لأن الشهر التالي سيبنى عليها في المتابعة، ولأن ذاكرة الانطباعات لا تحفظ شهرا كاملا بصدق كما يحفظه سجل مكتوب.</p>"
