      "head": "4) انتقال الشهر إلى الشهر",
      "body": "<p>حين يكتمل شهر وتبدأ خطة الشهر التالي، يخطئ من يتعامل مع الشهر الجديد كأنه بداية من الصفر، ويخطئ أيضا من يظن أن كل شهر يحتاج أساسا جديدا. فالخطة التالية تبني على البصمة نفسها ما لم تتغير تلك البصمة بإعادة تقييم في موعدها، وهو ما ستدرسه مفصلا في الدرس 12. معنى ذلك عمليا أن وسامات الأقسام التي قرأتها في أول الخطة، بأنماطها الغالبة في المجالات التسعة، تبقى هي مرجع القراءة والربط في الشهر الجديد أيضا: تقرأ أنشطته بمجالاتها، وتربط كل نشاط بوسام مجاله في قسمه، كما تعلمت في دروس قراءة الخطة الأولى. وما يتغير من شهر إلى شهر هو موضع التنفيذ داخل التدرج ومادة المتابعة المتراكمة، لا أساس البصمة نفسه. لذلك لا يعاد اختراع الأساس كل شهر: لا يعاد شرح البروفيل للأسرة كأنه جديد، ولا يعاد بناء توقعات من نقطة الصفر، ولا تلغى مراجعة الشهر السابق عند فتح الشهر الجديد. بل تحمل المراجعة المكتوبة إلى الشهر التالي بأسئلتها وتنبيهاتها، وتقرأ أسابيع الشهر الجديد في ضوئها. وبهذا التراكم وحده تصير المتابعة دورة حقيقية: قراءة، ثم تنفيذ، ثم ملاحظة وتسجيل، ثم مراجعة، ثم شهر جديد يبني على ما قبله، حتى يحين موعد إعادة التقييم فيولد بروفيل جديد وخطة جديدة بأساس جديد موثق.</p>"
