      "head": "5) موضع مجال اليوم من الخطة الكاملة",
      "body": "<p>من أكثر ما يلتبس على الأسر موضع مجال اليوم من الخطة الكاملة، وواجبك أن تشرحه بجملتين صافيتين قبل أن يبنى عليه أي توقع خاطئ. مجال اليوم نافذة عامة تفتح مجالا واحدا في يومه للجميع: مجال واحد في يوم محدد من الأسبوع، يطلع عليه الزائر والمتابع كما يطلع عليه المشترك، وهو هدية تعريف وتجربة محدودة بيومها ومجالها، ما فات منها في يومه لا يعوض في يوم آخر. أما الخطة فبرنامج شخصي كامل بمجالاته التسعة للمشترك وحده: أنشطة شهر كامل عددها يتبع بصمته ومبنية على بروفيل حالته هو، بأقسام مجالات وتدرج ومتابعة دورية تقرأ من الصفحة نفسها. فلا ينتظر من مجال اليوم ما لا يقدمه بطبيعته: هو لا يغطي المجالات التسعة، ولا يبني تدرجا شهريا، ولا يتابع تنفيذا، ولا يقيس أثرا. ولا تختزل الخطة في المقابل في مجال اليوم، كأن المشترك لا يحتاج إلا ما يفتح مجانا في يومه، لأن الخطة تخاطب بصمة كاملة بتسعة مجالات متداخلة، لا مجالا واحدا في يوم واحد. حين تشرح هذا الفرق بهدوء وبلا تقليل من قيمة النافذة العامة ولا تضخيم لها، تحمي الأسرة من خيبة توقع لم تصنعه المنظومة، وتحفظ للخطة موضعها الصحيح في ذهنها منذ أول أسبوع.</p>"
