      "head": "1) بنية جلسة تسليم الخطة",
      "body": "<p>ابدأ الجلسة دائمًا بترتيب الخطة نفسها، فالترتيب هنا جزء من الفهم. الخطوة الأولى بصمة الحالة باختصار: ذكّر الأسرة بالنمط المختار في كل مجال كما تظهر في وسامات أقسام الخطة، بلغة المستوى الثاني الآمنة نفسها، وصفًا وتكرارًا وأثرًا يوميًا، دون تشخيص ودون تضخيم لنسبة أو حالة. لا تعيد شرح التقرير كاملًا، بل ابنِ جسرًا قصيرًا يقول إن ما سيرونه في هذا الشهر مبني على هذه الصورة التي يعرفونها الآن.</p><p>الخطوة الثانية إيقاع الشهر كما تعلنه خطته: عدد أنشطة يتبع حالات مجالات البروفيل، فأنشطة للغالب والكامن ولا أنشطة للمتوازن، نشاط واحد يوميًا، ومدة النشاط كما في بطاقته، والأنشطة تتدرج عبر الشهور بمراحلها من التثبيت والاكتشاف إلى القيادة والاستقلالية. اشرح هذا الإيقاع بوصفه تصميمًا مقصودًا لا اقتراحًا قابلًا للضغط أو التكثيف، فأغلب أخطاء الشهر الأول تولد من محاولة تسريع هذا الإيقاع منذ الأسبوع الأول.</p><p>الخطوة الثالثة أقسام المجالات وبطاقة النشاط: افتح أمام الأسرة أقسام مجالات الشهر، وتتبع معها نشاطًا واحدًا من قسم مجاله إلى بطاقته الكاملة، المجال والمستوى والمدة والخطوات والمواد، حتى ترى الأسرة بعينها كيف يتحول نشاط في قسمه إلى نشاط ينفّذ في الغرفة. الخطوة الرابعة نشاط اليوم الأول عمليًا: نفّذه أمام الأسرة تنفيذًا حيًا قصيرًا بالمواد نفسها، ودع أحد الراشدين يشارك كما سيشارك في البيت، لأن الأسرة التي نفّذت مرة بيدها لا تحتاج شرحًا طويلًا بعد ذلك. الخطوة الخامسة والأخيرة: دور الأسرة وحدود الخدمة ومواعيد المراجعة وبروتوكول الدعم، وهي موضوع القسم التالي. لا تقفز في أي خطوة إلى النتائج، فجلسة التسليم جلسة فهم وتنفيذ، لا جلسة تنبؤ.</p>"
