      "head": "2) دور الأسرة المنفّذة لا المعالِجة",
      "body": "<p>عرّف الأدوار بجمل واضحة منذ اليوم الأول. الأسرة تنفّذ وتسجّل وتلاحظ: تنفّذ نشاط اليوم كما في بطاقته، وتعلّم إنجازه على بطاقته، وتسجّل الاستجابة بملاحظة موصوفة قصيرة، وتلاحظ ما يتغير في اليوم العادي عبر الأسابيع. الأسرة بهذا المعنى شريك تنفيذ وملاحظة، وليست معالِجة مطالبة بابتكار تدخلات أو بتعديل الخطة أو بتحمل مسؤولية نتائج لا تملك أدوات قياسها. هذا التحديد يخفف عنها عبئًا لا يخصها، ويمنح ملاحظاتها قيمة لأنها تأتي من موضعها الصحيح.</p><p>ودورك أنت أن تشرح وتتابع وتراجع: تشرح عند التسليم، وتتابع في مواعيد المراجعة المتفق عليها من سجل التنفيذ وملاحظات الأثر، وتراجع الشهر عند اكتماله قراءة كاملة قبل الانتقال إلى الشهر التالي. المتابعة إذن مواعيد معلومة ومراجعات موثقة، وليست مرافقة يومية ولا إجابة فورية عن كل يوم ولا تعديلات عند كل طلب. وهنا تضع عبارة نموذج أوسع في موضعها الطبيعي دون برود ودون اعتذار طويل: نبيع محتوى لا وقتنا. معناها العملي للأسرة أن قيمة ما تستلمه في الخطة نفسها وفي جلسات الشرح والمراجعة في مواعيدها، لا في حضور يومي مفتوح لا ينتهي.</p><p>وعند المشاكل يأتي بروتوكول الدعم الموحّد: أي مشكلة وصول إلى الخطة أو خطأ دخول أو عطل يمنع التنفيذ، ترسل الأسرة لقطة شاشة للمشكلة مع وصف مكتوب موجز إلى ماسنجر صفحة الأستاذ عبد الحليم خليلي، فلا تبليغ بلا لقطة. علّم الأسرة هذا البروتوكول في جلسة التسليم نفسها واكتبه لها، حتى لا تتحول أول مشكلة تقنية إلى رسائل متفرقة بلا دليل يسمح بمعالجتها.</p>"
