      "head": "3) ما يُشرح من مرونة الخطة المشروعة",
      "body": "<p>للخطة مرونة مقدمة داخلها، ومهمتك أن تشرحها كاملة لأنها خط الدفاع الأول ضد الرفض والاضطراب اليومي. أولها تبسيط الخطوة: إذا كان النشاط فوق قدرة اليوم، تبسّط خطوة النشاط نفسه، لا نشاط آخر من خارجها. وثانيها البطاقة البديلة من قسم المجال نفسه: بدائل موجودة داخل المنظومة في موضع معلوم، تستعمل عند حاجتها، ولا تحتاج اجتهادًا من المنفّذ. وثالثها التأجيل: نشاط اليوم الذي تعذّر لظرف حقيقي يؤجّل إلى الغد، ويُسجّل فواته وسببه، دون مضاعفة في اليوم التالي ودون تعويض مكدّس.</p><p>ومقابل هذه المرونة المشروعة حدود صريحة تقال في الجلسة نفسها بلغة هادئة لا تحذيرية. لا استبدال لنشاط بنشاط من خارج المنظومة باسم أوسع، فما لم يرد في الخطة ليس جزءًا منها مهما بدا قريبًا منها. ولا زيادة أنشطة من عند الأسرة أو من عندك بوصفها جزءًا من الخطة، فالزيادة العشوائية تفسد الإيقاع وتفسد قراءة الأثر لاحقًا. ولا تعديل في محتوى الخطة اجتهادًا، مهما بدا التعديل صغيرًا أو حسن النية. التعديل الوحيد المعتمد في مسار الحالة يأتي من المنظومة نفسها عبر بروفيل جديد عند إعادة التقييم في موعدها كل 5 أشهر، حين تخرج قراءة جديدة وتُبنى عليها خطة جديدة. بهذا الوضوح المزدوج، مرونة معلنة وحدود معلنة، تعرف الأسرة أين تتصرف بثقة وأين تقف وتنتظر المراجعة.</p>"
