      "head": "5) محظورات تسليم الخطة",
      "body": "<p>ثلاثة محظورات تغلق هذا الدرس وتضبط كل تسليم قادم. المحظور الأول وعد نتيجة: لا تقل إن الخطة ستحقق تغيرًا بعينه في زمن بعينه، ولا تلمّح إلى ذلك بصياغة ملطفة، فالوعد الضمني وعد كامل في ذاكرة الأسرة. ما تقوله بدلًا منه هو وصف أمين لما ستفعلونه معًا: تنفيذ صحيح، وتسجيل موثق، ومراجعة شهرية، وقياس بمؤشرات معلومة، وإعادة تقييم في موعدها.</p><p>المحظور الثاني تضخيم أثر نشاط واحد: لا تقدّم نشاطًا بعينه بوصفه مفتاح الحالة أو سبب تغير كبير قادم. الخطة وحدة شهرية متكاملة بتغطيتها وتدرجها وانتظامها، ونشاط واحد فيها لبنة لا بناء كامل. التضخيم يصنع خيبة حتمية حين لا يحدث الأثر الخارق الموعود ضمنيًا، ويشجع الأسرة على الانتقائية التي تفسد الشهر كله.</p><p>المحظور الثالث تقديم الخطة خطة علاجية شاملة أو بديلًا عن أي متابعة تخصصية أخرى. الخطة برنامج أنشطة حسية شهرية مبني على بروفيل الحالة، في فئتيه 0-3 و3-14، بمجالاته التسعة بترتيب التقييم: 1 الأصوات، 2 البصري، 3 اللمسية، 4 الشم والتذوق، 5 الحس العميق، 6 الدهليزية، 7 الحس الداخلي، 8 الاجتماعي-عاطفي، 9 الانتباه والتركيز. وهي لا تلغي تقييمًا آخر تحتاجه الحالة، ولا تحل محل متابعة تخصصية قائمة، ولا تتسع لأسئلة التشخيص أو البرامج الشاملة، وتلك الأسئلة موضعها الإحالة بطريقتها المعتمدة لا الاجتهاد في جلسة التسليم. من قال حدود خطته بوضوح في أول جلسة، لم يحتج إلى التراجع عن وعوده في آخر شهر.</p>"
