      "head": "3) حدّ التمثيل الثاني الصارم",
      "body": "<p>يعلن هذا الدرس حدّ التمثيل الثاني صراحة ودون أي استثناء: لا تشرح بناء الخطة من الداخل لأي متدرب أبدًا، لا وليًا ولا مختصًا ولا شريكًا محتملًا. هذا الحد امتداد مباشر لحد المستوى الثاني في شرح النواتج دون ما وراءها: ما تملكه وتقدّمه بلا حدود هو الخطة كما تصل المشترك، مكوناتها الظاهرة، وقراءة تطابقها الظاهر مع البروفيل، وتنفيذها ومتابعتها وقياس أثرها وإعادة التقييم في موعدها. وما وراء هذا الظاهر ليس مادة تدريب عندك، ولا تلمّح إليه، ولا تؤكد تخمينًا طرحه سائل ولا تنفيه، فالتأكيد والنفي معًا كشف مقنّع.</p><p>وحين يصلك السؤال المباشر بصيغه المختلفة، لماذا جاء هذا النشاط بعينه، أو على أي أساس رُتّبت الأنشطة، أجب بالجملة الثابتة الواحدة التي لا تتغير بتغير السائل ولا بتغير إلحاحه: كيف تُبنى الخطة من الداخل ليس جزءًا مما أقدّمه، وهو عند الأستاذ عبد الحليم خليلي وحده، وسأحيل سؤالك إليه إن رغبت. لا تضف بعد هذه الجملة أي تفسير تقريبي، ولا تقل إنه سؤال بسيط لكنه ممنوع، ولا تعتذر بإفراط، فكل إضافة تفتح بابًا أغلقته الجملة. ثم تابع جلستك من موضعها كأن شيئًا لم ينقطع، فالحد الممارس بهدوء يعلّم المتدربين احترامه أكثر من أي شرح عن أهميته.</p><p>وهذا الحد ليس نقصًا في تأهيلك، هو تعريف دقيق له: أنت مدرّب تنفيذ ومتابعة وقياس، وممثّل لطريقة في نواتجها الظاهرة، ولست ناقلًا لما وراء إنتاجها. الشريك الذي يحفظ هذا الحد تحت إلحاح أسئلة ذكية ومتكررة هو تحديدًا الشريك الذي يصلح أن يمثّل أوسع أمام غيره.</p>"
