      "head": "4) تمثيل أوسع أمام المختصين في متابعة الخطط",
      "body": "<p>في تدريبات المختصين داخل عيادتك تقدّم متابعة الخطط كاملة بعمقها المهني: قراءة خطة من بروفيلها الظاهر، وبنية الشهر وتدرجه، وقواعد التنفيذ الآمن، وإدارة الرفض بسلّمه، ونوعا التسجيل وتدقيق السجلات، وقراءة التقدم ومراجعة اكتمال الشهر، ومؤشرات قياس الأثر الأربعة وخط الأساس، وإدارة موعد إعادة التقييم وموازنة بروفيلين دون حكم نسبة واحدة، وأخطاء إدارة الخطة وحدودها وحالات إحالتها كما في الدرس الأخير من هذا المستوى. هذا محتوى تمثيلك الكامل، وهو كبير ويكفي تدريبات كاملة، ولا يحتاج أي زيادة من خارج حدودك ليبدو قيّمًا.</p><p>وما لا تقدّمه صريح كذلك، ويقال بلا تردد. لا تبني خططًا باسم أوسع لأي حالة، فأنت تدير خطة مقدمة وتتابعها ولا تنتجها. ولا تعتمد شركاء جدد ولا توحي لأحد بقرب اعتماد ولا تقدّم نفسك بوابة للانضمام إلى المنظومة، فالاعتماد قرار الأستاذ عبد الحليم خليلي وحده. ولا تتفاوض باسم أوسع على أي اتفاق مع مختص أو جهة، ولا تعد أحدًا بتدريب متقدم أو بامتياز قادم لم يعلنه الأستاذ عبد الحليم خليلي. دورك مع مختص مهتم بما وراء المتابعة ينتهي عند توجيه واحد هادئ: أستطيع أن أدرّبك على قراءة الخطة ومتابعتها وقياس أثرها، وما تجاوز ذلك طريقه الأستاذ عبد الحليم خليلي مباشرة، ثم تحيله بقناة التواصل المعتمدة. كل تجاوز لهذه الحدود، ولو بحماس صادق لمساعدة زميل، يخلق التزامات باسم أوسع لم يقرها صاحبها.</p>"
