      "head": "5) بروتوكول الدعم أثناء تدريباته وتنفيذه",
      "body": "<p>أثناء تدريباتك ومتابعاتك قد تظهر مشاكل عملية لا علاقة لها بالمحتوى: مشكلة وصول إلى خطة، أو كود أنشطة لا يفتح، أو خطأ دخول عند ولي أو مختص متدرب. لهذه المشاكل كلها بروتوكول دعم موحّد واحد لا يتغير بتغير نوع المشكلة ولا بتغير صاحبها: لقطة شاشة للمشكلة كما تظهر على الشاشة، ووصف مكتوب موجز لما حدث ومتى حدث وما سبقه، يرسلان معًا إلى ماسنجر صفحة الأستاذ عبد الحليم خليلي. لا تبليغ بلا لقطة، فالوصف وحده لا يسمح بتشخيص مشكلة تقنية، واللقطة وحدها بلا وصف لا تقول في أي سياق ظهرت.</p><p>ولا تجرّب حلولًا من عندك على حسابات المتدربين أو أكوادهم أثناء الجلسة، فكل تجربة قد تحوّل مشكلة دخول بسيطة إلى خلل في بيانات حالة كاملة. دورك أن توثّق المشكلة باللقطة والوصف، وترسلها بطريقتها، وتتابع جلستك في أجزائها التي لا تتوقف على الحل، ثم تعود إلى صاحب المشكلة بما يصلك من توجيه. وعلّم هذا البروتوكول لمتدربيك في آخر كل جلسة بوصفه جزءًا من الطريقة نفسها: الشريك الممثّل ينقل النظام كما ينقل المحتوى.</p>"
