     "text": {
      "head": "1) أخطاء إدارة الخطة الخمسة",
      "body": "<p>الخطأ الأول: التنفيذ الانتقائي. تنفّذ الأسرة، أو يوجّه الشريك ضمنيًا، مجالات محببة سهلة وتُهمل مجالات أخرى شهرًا كاملًا، فتنكسر تغطية الشهر التي تقوم عليها الخطة: أنشطة موزعة على مجالاتها الفعالة كلها بحسب حالاتها، والمجالات الفعالة كلها تمر عبر الشهر. الانتقائية لا تظهر في يوم واحد، تظهر في مراجعة الشهر حين تجد مجالًا منفّذًا كاملًا ومجالًا لم يمس تقريبًا. وضبطها يكون بقراءة التغطية على الشهر كاملًا في كل مراجعة، لا بملاحقة الأسرة نشاطًا نشاطًا.</p><p>الخطأ الثاني: مضاعفة الأنشطة بدافع الحماس. نشاطان أو ثلاثة في اليوم بدل نشاط واحد بمدة بطاقته، بدعوى تسريع الأثر. المضاعفة تفسد الإيقاع المعلن، وتحوّل الخطة من عادة يومية خفيفة قابلة للاستمرار إلى عبء ينهك المتعلم والأسرة حتى الانقطاع، وتفسد قياس الأثر لأن الجرعة الفعلية لم تعد هي الجرعة المدروسة في السجل. الحماس المشروع عنوانه الانتظام، لا التكثيف.</p><p>الخطأ الثالث: إيقاف الخطة كلها عند أول رفض. يقابل المتعلم نشاطًا بالرفض فيتوقف الشهر كله أيامًا أو يُهجر نهائيًا، بدل سلم الرفض الذي درسته: إيقاف هادئ، وفحص للسياق، وتبسيط خطوة في محاولة لاحقة، وتأجيل، وتسجيل موصوف. الرفض الواحد معلومة عن نشاط ويوم، فإذا عومل بوصفه حكمًا على الخطة كلها ضاع شهر كامل بسبب موقف واحد.</p><p>الخطأ الرابع: قراءة أسبوع واحد حكمًا على الخطة كلها. أسبوع سلس فيُعلن نجاح الخطة، أو أسبوع مضطرب فيُعلن فشلها، والحقيقة أن الأثر يُقاس عبر الشهور بمؤشرات موثقة وبمراجعات متراكمة وخط أساس معلوم، لا من سبعة أيام مهما بدت لافتة. هذا الخطأ هو الوجه الإداري لخطأ القياس الذي ضبطه درس قياس الأثر، وعلاجه واحد: لا حكم قبل مراجعة شهر، ولا خلاصة قبل تراكم شهور.</p><p>الخطأ الخامس: تعديل الخطة اجتهادًا. استبدال نشاط بنشاط من خارج الخطة، أو إضافة أنشطة من عند المنفّذ أو الشريك بوصفها جزءًا منها، أو تغيير محتواها بأي صورة خارج مرونتها المقدمة، تبسيط الخطوة والبدائل من القسم نفسه والتأجيل. التعديل الاجتهادي يقطع صلة التنفيذ الفعلي بالخطة المدروسة في المراجعة، فيصبح السجل وثيقة لشيء آخر غير الخطة، ويصبح قياس الأثر كله بلا موضوع. من رصد هذه الأخطاء الخمسة واحدًا واحدًا في كل سجل يعرض عليه، فقد امتلك عين مدير الخطة لا عين منفّذها فقط.</p>"
     }
