     "text": {
      "head": "2) حدود الخطة",
      "body": "<p>للخطة حدود ثلاثة تقال للأسرة عند التسليم، وتُستحضر عند كل مراجعة، ويقف عندها كلام الشريك كما يقف كلامه عند حدود التقرير من قبل. الحد الأول تعريفي: الخطة برنامج أنشطة حسية شهرية مبني على بروفيل الحالة، بنشاط يومي قصير وتغطية للمجالات التسعة بترتيب التقييم، 1 الأصوات، 2 البصري، 3 اللمسية، 4 الشم والتذوق، 5 الحس العميق، 6 الدهليزية، 7 الحس الداخلي، 8 الاجتماعي-عاطفي، 9 الانتباه والتركيز، وفي فئتي الأداة 0-3 و3-14. هذا هو موضوعها الكامل، وكل ما خرج عنه ليس نقصًا فيها بل خروج عن تعريفها.</p><p>الحد الثاني: الخطة ليست خطة علاجية شاملة، ولا بديلًا عن تقييمات أو متابعات تخصصية أخرى تحتاجها الحالة. متعلم يتابع في مسارات تخصصية أخرى يبقى متابعًا فيها، والخطة تعمل في موضعها الحسي الشهري دون أن تلغي موضع غيرها أو تنافسه أو تدّعي تغطيته. الشريك الذي يقدّم الخطة في حدودها يحمي أسرته من إيقاف متابعات ضرورية اعتمادًا على وهم الشمول، ويحمي الخطة نفسها من أن تُحاسَب على نتائج لم تكن يومًا من وعدها.</p><p>الحد الثالث: لا وعد في الخطة بنتيجة بعينها، لا بمقدار ولا بموعد ولا بصورة محددة للتغير. ما تعد به المنظومة هو مسار صحيح موثق: خطة مبنية على بروفيل، وتنفيذ منتظم مرن في حدوده المعلنة، وتسجيل صادق، ومراجعات شهرية، وقياس بمؤشرات قابلة للملاحظة، وإعادة تقييم كل 5 أشهر تخرج منها قراءة جديدة وخطة جديدة. من باع الأسرة نتيجة بعينها باعها ما لا يملك، ومن باعها مسارًا صحيحًا قال كل ما يستطيع قوله بصدق.</p>"
     }
