     "text": {
      "head": "3) متى تُحال الحالة إلى الأستاذ عبد الحليم خليلي أثناء إدارة الخطة",
      "body": "<p>تُحال الحالة إلى الأستاذ عبد الحليم خليلي أثناء إدارة الخطة في أربع حالات واضحة، والإحالة في كل منها واجب مهني لا اعتراف بعجز. الحالة الأولى: رفض شامل موثق مستمر. يرفض المتعلم الأنشطة كلها أو جلها أيامًا متتالية رغم تطبيق المرونة الكاملة، تبسيط خطوة وتأجيلًا وفحصًا للسياق وتغييرًا للتوقيت، ويوثّق ذلك في السجل توثيقًا موصوفًا. هنا ينتهي موضع الاجتهاد المحلي، فالرفض الشامل المستمر رسالة تحتاج قراءة صاحب المنظومة لا مزيدًا من الإصرار.</p><p>الحالة الثانية: تراجع سلوكي موثق متزامن مع التنفيذ. يظهر في سجل الأثر تدهور متكرر في سلوك مستهدف أو في يوم المتعلم عمومًا، متزامنًا مع استمرار التنفيذ وموثقًا عبر أيام لا من موقف واحد. التزامن وحده لا يثبت سببًا، لكنه يستوجب الرفع بوصفه معلومة، ولا يستوجب أبدًا أن يعدّل الشريك الخطة من عنده أو يوقفها كلها بقرار منفرد بانتظار الجواب.</p><p>الحالة الثالثة: ألم أو اشتباه عضوي يظهر مع أنشطة بعينها. شكوى ألم متكررة، أو علامة جسدية تظهر مع نوع بعينه من الأنشطة، فالإحالة الطبية هنا هي الأصل الذي لا يؤجل، ويُعلم الأستاذ عبد الحليم خليلي بالتوازي بوصف مكتوب لأن الحالة خرجت عن مسار الإدارة المعتاد. السلامة الجسدية تتقدم دائمًا على استكمال أي جدول.</p><p>الحالة الرابعة: طلبات أسرة تتجاوز نطاق الأداة والخطة إلى تشخيص أو برنامج شامل. تطلب الأسرة باسم أوسع تشخيصًا لحالتها أو خطة علاجية جامعة أو حكمًا في مسار تخصصي آخر، فلا يُجاب عن أي منها اجتهادًا من مقعد إدارة الخطة، بل تُرفع كما هي. وطريقة الإحالة مكتوبة ومعتمدة: وصف موجز مكتوب يرسل إلى ماسنجر صفحة الأستاذ عبد الحليم خليلي، يذكر الحالة وسبب الرفع بجمل دقيقة وما يدعمه من سجل موثق، ولقطة شاشة ترافق الوصف عند كون المشكلة تقنية، فلا تبليغ تقني بلا لقطة. وبعد الإحالة يقف دورك عند جملة واحدة للأسرة: رفعت الأمر مكتوبًا إلى الأستاذ عبد الحليم خليلي وسأعود إليكم بجوابه، دون استباق للجواب بتخمين أو وعد.</p>"
     }
